function getAlteryxAiTranslation(key, lang) {
    return (alteryxaiTranslations[lang] && alteryxaiTranslations[lang][key]) ||
           (alteryxaiTranslations.en && alteryxaiTranslations.en[key]) || null;
}

function applyAlteryxAiTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.alteryx-ai.") || key.startsWith("review.common."))) {
            const translation = getAlteryxAiTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    
}

window.addEventListener("languageChanged", e => setTimeout(() => applyAlteryxAiTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyAlteryxAiTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyAlteryxAiTranslations(window.i18n?.getCurrentLanguage() || "en");
}
